const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Both original rows use this one coordinate frame: x24..336 is exactly one whole.
export function ribbonMatchesDiagram(source,index,{workingDescription=''}={}){
 const left=24,width=312,height=34,referenceEnd=width*source.referenceNumerator/source.referenceDenominator;
 const row=(kind,y,den,end)=>{const partitions=Array.from({length:den-1},(_,i)=>`<line x1="${left+width*(i+1)/den}" y1="${y}" x2="${left+width*(i+1)/den}" y2="${y+height}"/>`).join('');return `<g data-ribbon-match-row="${kind}" data-whole-left="${left}" data-whole-width="${width}" data-whole-height="${height}"><rect class="ribbon-match-whole" x="${left}" y="${y}" width="${width}" height="${height}"/>${end===null?'':`<rect class="ribbon-match-prefix" x="${left}" y="${y}" width="${end}" height="${height}"/><path class="ribbon-match-prefix-edge" d="M${left} ${y+height-4}H${left+end}"/>`}<g class="ribbon-match-cuts">${partitions}</g><rect class="ribbon-match-outline" x="${left}" y="${y}" width="${width}" height="${height}"/>${end===null?'':`<g class="ribbon-match-flag" data-ribbon-match-endpoint="${12*end/width}"><path d="M${left+end} ${y+height+8}V${y-16}l12 6-12 6"/></g>`}<path class="ribbon-match-bracket" d="M${left} ${y+height+16}v6H${left+width}v-6"/><text x="${left}" y="${y+height+42}" text-anchor="middle">0</text><text x="${left+width}" y="${y+height+42}" text-anchor="middle">1</text></g>`;};
 return `<svg class="ribbon-match-diagram" viewBox="0 0 360 280" role="img" aria-label="${esc('Two equal whole ribbons. Fixed reference: '+source.referencePictureText+' Our working ribbon: '+workingDescription)}" focusable="false"><text class="ribbon-match-row-name" x="24" y="26">Fixed reference</text>${row('reference',54,source.referenceDenominator,referenceEnd)}<text class="ribbon-match-row-name" x="24" y="152">Our working amount</text>${row('working',180,source.workingDenominator,index===null?null:width*index/source.workingDenominator)}</svg>`;
}
